using Godot;
using System;
public partial class ImageWorkspaceOperations
{
    public void save_selection(Control owner)
    {
        var canvas=Canvas(owner);if(canvas.Get("selection").AsGodotObject()==null){owner.Get("status").As<Label>().Text="Draw a selection first.";return;}var dialog=new ConfirmationDialog{Title="Save selection"};owner.AddChild(dialog);var input=new LineEdit{Text="Selection "+(Document(owner).Get("selections").AsGodotDictionary().Count+1),CustomMinimumSize=new Vector2(280,0)};dialog.AddChild(input);dialog.Confirmed+=()=>{if(input.Text.Trim().Length>0)Action(owner,()=>Document(owner).Get("selections").AsGodotDictionary()[input.Text.Trim()]=ImageTexture.CreateFromImage(canvas.Get("selection").As<Image>()));};CloseWithDialog(dialog);dialog.PopupCentered(new Vector2I(340,120));input.GrabFocus();input.SelectAll();
    }
    public void load_selection(Control owner)
    {
        var selections=Document(owner).Get("selections").AsGodotDictionary();if(selections.Count==0){owner.Get("status").As<Label>().Text="No saved selections in this document yet.";return;}var popup=new PopupMenu();owner.AddChild(popup);var names=new System.Collections.Generic.List<string>();foreach(var key in selections.Keys){names.Add(key.AsString());popup.AddItem(key.AsString());}popup.IdPressed+=index=>{using var selection=selections[names[(int)index]].As<Texture2D>().GetImage();var size=Document(owner).Get("canvas_size").AsVector2I();if(selection.GetSize()!=size)selection.Resize(size.X,size.Y,Image.Interpolation.Nearest);commit_selection_bitmap(owner,selection);};popup.PopupHide+=popup.QueueFree;popup.Position=(Vector2I)owner.GetGlobalMousePosition();popup.Popup();
    }
    public void selection_panel(Control owner)
    {
        var ui=workflow_window(owner,"Smart selection & masks",new Vector2(720,500));var body=ui["body"].As<VBoxContainer>();var smart=panel_card(body,"Smart pixel selection","Build editable selections from the active layer, then refine them non-destructively.");var actions=new HFlowContainer();smart.AddChild(actions);foreach(var entry in new[]{("Select subject","opaque","Select all non-transparent pixels"),("Select background","transparent","Select transparent background pixels"),("Select highlights","highlights",""),("Select shadows","shadows","")})button(owner,actions,entry.Item1,Callable.From(()=>owner.Call("_smart_select",entry.Item2,Colors.Transparent,.12)),entry.Item3,"");button(owner,actions,"Select similar color…",Callable.From(()=>select_similar_dialog(owner)),"","");var refine=new HFlowContainer();smart.AddChild(refine);foreach(var entry in new[]{("Grow 2 px","grow",2),("Shrink 2 px","shrink",2),("Feather 3 px","feather",3),("Smooth","smooth",2)})button(owner,refine,entry.Item1,Callable.From(()=>modify_selection(owner,entry.Item2,entry.Item3)),"","");button(owner,refine,"Invert   Ctrl+I",Callable.From(()=>invert_selection(owner)),"","");button(owner,refine,"Clear",Callable.From(()=>{Action(owner,()=>{Document(owner).Set("pixel_selection",default(Variant));Document(owner).Set("pixel_selection_reference",default(Variant));});_canvas.clear_selection(Canvas(owner));}),"","");var masks=panel_card(body,"Layer masks & clipping","Masks stay editable; clipping uses the opacity of the layer directly below.");var maskActions=new HFlowContainer();masks.AddChild(maskActions);button(owner,maskActions,"Selection → mask",Callable.From(()=>selection_to_mask(owner)),"","");button(owner,maskActions,"Mask → selection",Callable.From(()=>mask_to_selection(owner)),"Load the current layer mask into the pixel-selection brush for editing","");button(owner,maskActions,"Opacity → mask",Callable.From(()=>source_to_mask(owner,false)),"","");button(owner,maskActions,"Luminance → mask",Callable.From(()=>source_to_mask(owner,true)),"","");button(owner,maskActions,"Invert mask",Callable.From(()=>invert_layer_masks(owner)),"","");button(owner,maskActions,"Clear mask",Callable.From(()=>Action(owner,()=>{foreach(var id in Canvas(owner).Get("selected").AsGodotArray()){var layer=_documents.layer_for_id(Document(owner),id.AsString());layer?.Set("mask",default(Variant));}})),"","");button(owner,maskActions,"Toggle clip below",Callable.From(()=>Action(owner,()=>{foreach(var id in Canvas(owner).Get("selected").AsGodotArray()){var layer=_documents.layer_for_id(Document(owner),id.AsString());if(layer!=null)layer.Set("clip_to_below",!layer.Get("clip_to_below").AsBool());}})),"","");button(owner,maskActions,"Adjustment group",new Callable(owner,"_create_adjustment_group"),"Wrap selected layers in a group whose effects adjust the whole group","");ui["popup"].As<PopupPanel>().PopupCentered();
    }
}
